package net.minecraft.client.multiplayer;import java.util.*;import net.minecraft.world.entity.Entity;import net.minecraft.core.BlockPos; public class ClientLevel {public final Map<Integer,Entity> entities=new LinkedHashMap<>();public boolean chunks=true;public Runnable onChunkQuery;public long time=47;public Entity getEntity(int id){return entities.get(id);}public boolean hasChunkAt(BlockPos p){Runnable callback=onChunkQuery;onChunkQuery=null;if(callback!=null)callback.run();return chunks;}public long getGameTime(){return time;}}
